-- 검증(읽기 전용): ap_human_geography. ok 가 모두 true 여야 한다.
select 'subject' as check, 1 as expected, (select count(*) from subjects where ap_subject_code = 'ap_human_geography') as actual, 1 = (select count(*) from subjects where ap_subject_code = 'ap_human_geography') as ok
union all
